"""Phase 6 — tableau de bord Administration BÉCHÉFAA.

Point d'entrée isolé et en lecture seule vers les modules déjà validés.
Aucune logique métier de caisse, paiement, cuisine, catalogue ou Z n'est modifiée.
"""
from flask import Response


def register_admin_dashboard_isolated_phase6(app):
    @app.get("/administration")
    def admin_dashboard_phase6():
        html = r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BÉCHÉFAA • Administration</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f4f6;color:#111827;font-family:Arial,sans-serif}.top{background:#111827;color:#fff;padding:15px 22px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top b{font-size:21px}.top .spacer{flex:1}.top a{color:#fff;text-decoration:none;background:#263244;padding:9px 12px;border-radius:8px;font-weight:800}.wrap{max-width:1200px;margin:0 auto;padding:26px 18px 38px}.hero{background:linear-gradient(135deg,#111827,#263244);color:#fff;border-radius:18px;padding:24px;margin-bottom:18px}.hero h1{margin:0 0 7px;font-size:30px}.hero p{margin:0;color:#d1d5db}.status{display:inline-flex;align-items:center;gap:7px;margin-top:14px;padding:7px 10px;border-radius:99px;background:#ffffff14;font-size:13px;font-weight:800}.dot{width:9px;height:9px;border-radius:50%;background:#22c55e}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.metric{background:#fff;border-radius:14px;padding:17px;box-shadow:0 2px 12px #0001}.metric .label{font-size:12px;text-transform:uppercase;color:#667085;font-weight:900}.metric .value{font-size:25px;font-weight:900;margin-top:7px}.section-title{margin:25px 0 11px;font-size:20px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{display:block;background:#fff;color:#111827;text-decoration:none;border:1px solid #e5e7eb;border-radius:15px;padding:18px;min-height:125px;box-shadow:0 2px 12px #0001;transition:.15s transform,.15s border-color}.card:hover{transform:translateY(-2px);border-color:#9ca3af}.icon{font-size:25px;margin-bottom:9px}.card b{display:block;font-size:17px;margin-bottom:5px}.card span{display:block;color:#667085;font-size:13px;line-height:1.35}.danger{border-color:#fecaca}.danger b{color:#b91c1c}.cash{border-color:#fde68a}.cash b{color:#92400e}.note{margin-top:22px;background:#fff;border-left:4px solid #111827;border-radius:10px;padding:13px 15px;color:#475467;font-size:13px}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.metrics,.grid{grid-template-columns:1fr}.hero h1{font-size:25px}.wrap{padding:16px 12px 28px}}
</style></head><body><header class="top"><b>BÉCHÉFAA • Administration</b><span class="spacer"></span><a href="/pos">Caisse</a><a href="/cuisine">Cuisine</a></header><main class="wrap"><section class="hero"><h1>Tableau de bord</h1><p>Accès centralisé aux fonctions de gestion de BÉCHÉFAA-Caisse.</p><div class="status"><span class="dot"></span><span id="dbstate">PostgreSQL • vérification…</span></div></section><section class="metrics"><div class="metric"><div class="label">Commandes aujourd'hui</div><div class="value" id="mOrders">—</div></div><div class="metric"><div class="label">CA commandes</div><div class="value" id="mGross">—</div></div><div class="metric"><div class="label">Panier moyen</div><div class="value" id="mAvg">—</div></div><div class="metric"><div class="label">Net encaissé</div><div class="value" id="mNet">—</div></div></section><h2 class="section-title">Gestion</h2><section class="grid"><a class="card" href="/administration/produits"><div class="icon">🍔</div><b>Produits / Carte</b><span>Créer, modifier et activer les produits du catalogue.</span></a><a class="card" href="/administration/categories"><div class="icon">🗂️</div><b>Catégories</b><span>Ajouter et renommer les catégories. Suppression autorisée uniquement pour une catégorie vide.</span></a><a class="card" href="/administration/options-produits"><div class="icon">⚙️</div><b>Options & suppléments</b><span>Groupes, choix, règles et prix des options produits.</span></a><a class="card" href="/clients"><div class="icon">👤</div><b>Clients</b><span>Rechercher et modifier les fiches clients.</span></a><a class="card" href="/historique-modification"><div class="icon">🧾</div><b>Commandes / Historique</b><span>Consulter l'historique et accéder aux commandes modifiables.</span></a><a class="card" href="/historique-modification"><div class="icon">💳</div><b>Paiements / Remboursements</b><span>Encaisser, consulter les paiements et gérer les remboursements depuis l'historique.</span></a><a class="card" href="/statistiques"><div class="icon">📊</div><b>Statistiques / Rapports</b><span>CA, panier moyen, remboursements, produits et canaux de vente.</span></a></section><h2 class="section-title">Caisse & clôture</h2><section class="grid"><a class="card cash" href="/maintenance/phase44/cash-float-opening"><div class="icon">💶</div><b>Fond de caisse</b><span>Enregistrer le fond d'ouverture de la journée.</span></a><a class="card cash" href="/maintenance/phase44/cash-count-save"><div class="icon">🪙</div><b>Comptage espèces</b><span>Enregistrer le comptage réel des espèces avant clôture.</span></a><a class="card" href="/caisse/x"><div class="icon">🧮</div><b>X de caisse</b><span>État intermédiaire en lecture seule, sans clôturer.</span></a><a class="card danger" href="/caisse/z"><div class="icon">🔒</div><b>Z de fin de journée</b><span>Clôture définitive après contrôle des commandes et espèces.</span></a><a class="card" href="/caisse/z/archive"><div class="icon">📚</div><b>Archives Z</b><span>Consulter et imprimer les clôtures déjà enregistrées.</span></a></section><h2 class="section-title">Paramètres</h2><section class="grid"><a class="card" href="/parametres"><div class="icon">🖨️</div><b>Matériel</b><span>Imprimante, tiroir-caisse et configuration du poste.</span></a><a class="card" href="/parametres/restaurant"><div class="icon">🏪</div><b>Restaurant</b><span>Identité commerciale et informations administratives.</span></a><a class="card" href="/securite"><div class="icon">🔐</div><b>Sécurité / Accès</b><span>Configurer les codes PIN et ouvrir la zone interne protégée.</span></a></section><div class="note"><b>Administration BÉCHÉFAA.</b> Ce tableau centralise les modules de gestion déjà disponibles sans modifier leur logique métier. Le paiement en ligne reste volontairement séparé de cette étape.</div></main><script>
const euro=n=>Number(n||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR'});async function loadDashboard(){try{let h=await fetch('/api/health',{cache:'no-store'}),hd=await h.json();document.getElementById('dbstate').textContent=(h.ok&&hd.ok?'PostgreSQL • opérationnel':'Service à vérifier')}catch(e){document.getElementById('dbstate').textContent='Service à vérifier'}try{let r=await fetch('/api/statistics/today-phase44?period=today',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Erreur');document.getElementById('mOrders').textContent=d.orders.count;document.getElementById('mGross').textContent=euro(d.orders.gross_total);document.getElementById('mAvg').textContent=euro(d.orders.average_ticket);document.getElementById('mNet').textContent=euro(d.cashflow.net)}catch(e){['mOrders','mGross','mAvg','mNet'].forEach(id=>document.getElementById(id).textContent='—')}}loadDashboard();
</script></body></html>'''
        return Response(html, content_type="text/html; charset=utf-8")
